import { chromium, expect } from '@playwright/test'
const browser = await chromium.launch({ executablePath: process.env.WARDAH_BROWSER_EXECUTABLE || undefined,
  headless: true, args: ['--no-sandbox', '--disable-dev-shm-usage', '--single-process', '--no-zygote'] })
try {
  const context = await browser.newContext()
  await context.route('**/*', route => new URL(route.request().url()).hostname === '127.0.0.1' ? route.continue() : route.abort())
  const page = await context.newPage(); const errors = []
  page.on('pageerror', e => errors.push(e.message))
  page.on('console', e => { if (e.type() === 'error') errors.push(e.text()) })
  const state = () => page.evaluate(async () => (await fetch('/state')).json())
  await page.goto('http://127.0.0.1:4177')
  await expect(page.getByLabel('Manufacturing order')).toBeEnabled()
  const initial = await state()
  expect(await page.evaluate(() => window.__operator.create())).toBe(true)
  const created = await state()
  const mo = created.manufacturing_orders.find(r => r.order_number === 'MO-OPERATOR-COMBINED')
  expect(mo.status).toBe('draft'); expect(mo.item_id).toBeNull()
  const wo = await page.evaluate(id => window.__operator.prepare(id), mo.id)
  await page.getByLabel('Fixture order ID').fill(mo.id)
  await page.getByRole('button', { name: 'Open stage form', exact: true }).click()
  const form = page.getByRole('dialog')
  const selectors = form.getByRole('combobox')
  await selectors.nth(0).click(); await page.getByRole('option', { name: 'Combined MO', exact: true }).click()
  await selectors.nth(1).click(); await page.getByRole('option', { name: 'Combined stage', exact: true }).click()
  await expect(form.getByLabel('تكلفة العمل')).toHaveCount(0)
  await form.getByRole('button', { name: 'حفظ', exact: true }).click()
  await expect(form).toHaveCount(0)
  const prepared = await state()
  const wip = prepared.stage_wip_log.find(r => r.mo_id === mo.id)
  const res = prepared.material_reservations.find(r => r.mo_id === mo.id)
  expect(wip.cost_material).toBe(0); expect(res.quantity_reserved).toBe(25)
  await page.reload()
  await page.getByLabel('Manufacturing order').selectOption(mo.id)
  await expect(page.getByLabel('Reserved material 1')).toBeEnabled()
  const ctx = await page.evaluate(async id => (await fetch('/call', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ kind: 'rpc', name: 'rpc_get_material_issue_context', args: { p_mo_id: id } }),
  })).json(), mo.id)
  const options = ctx.data
  for (const [label, value] of [['Stage', wip.stage_id], ['Reserved material 1', res.id], ['Work order 1', wo],
    ['Warehouse 1', options.warehouses.find(r => r.product_ids.includes(res.product_id)).id], ['Base unit 1', res.uom_id]]) {
    await page.getByLabel(label, { exact: true }).selectOption(value)
  }
  await page.getByLabel('Quantity 1', { exact: true }).fill('10')
  await page.evaluate(() => localStorage.setItem('operator:lose-issue', 'true'))
  await page.getByRole('button', { name: 'Issue materials', exact: true }).click()
  await expect(page.getByRole('button', { name: 'Retry saved event', exact: true })).toBeEnabled()
  const posted = await state()
  const consumption = posted.material_consumption.filter(r => r.mo_id === mo.id)
  expect(consumption).toHaveLength(1)
  expect(posted.stage_wip_log.find(r => r.id === wip.id).cost_material).toBe(100)
  expect(posted.material_reservations.find(r => r.id === res.id).quantity_consumed).toBe(10)
  expect(posted.events.filter(r => r.mo_id === mo.id)).toHaveLength(1)
  expect(posted.stock_ledger_entries.length - prepared.stock_ledger_entries.length).toBe(1)
  const onHand = rows => rows.filter(r => r.product_id === res.product_id).reduce((n, r) => n + Number(r.actual_qty), 0)
  expect(onHand(prepared.bins) - onHand(posted.bins)).toBe(10)
  await page.reload(); await page.getByLabel('Manufacturing order').selectOption(mo.id)
  await page.getByRole('button', { name: 'Retry saved event', exact: true }).click()
  await expect(page.getByText('Issue confirmed. Receipt:', { exact: false })).toBeVisible()
  const replayed = await state()
  const financial = snapshot => Object.fromEntries(Object.entries(snapshot).filter(([key]) => key !== 'trace'))
  expect(financial(replayed)).toEqual(financial(posted))
  const calls = replayed.trace.filter(r => r.name === 'rpc_consume_material_event')
  expect(calls).toHaveLength(2); expect(calls[1].args).toEqual(calls[0].args)
  await page.evaluate(id => window.__operator.release(id), res.id)
  const released = await state(); const history = released.material_reservations.find(r => r.id === res.id)
  expect(history.quantity_consumed).toBe(10); expect(history.quantity_released).toBe(15)
  expect(history.status).toBe('released')
  expect(released.stage_wip_log.find(r => r.id === wip.id).cost_material).toBe(100)
  expect(released.material_consumption).toEqual(posted.material_consumption)
  expect(released.stock_ledger_entries).toEqual(posted.stock_ledger_entries)
  expect(released.bins).toEqual(posted.bins)
  for (const table of ['gl_entries', 'gl_entry_lines', 'journal_entries']) expect(released[table]).toEqual(initial[table])
  expect(errors).toEqual([])
  console.log('COMBINED_PRODUCT_FORM_PRISTINE_WIP_REAL_PG_PASS')
  console.log('COMBINED_BROWSER_M192_LOST_RESPONSE_RELOAD_REPLAY_STATE_EQUAL_PASS')
  console.log('COMBINED_RELEASE_PRESERVES_HISTORY_STOCK_WIP_GL_PASS')
  console.log('COMBINED_TECHNICAL_ACCEPTANCE_PASS — fixed simulated identity/local PG adapter; not live Auth or operator UX sign-off')
  await context.close()
} finally { await browser.close() }
